  'aiworkspace.demo.quarterly.introTitle': 'Analyse d’activité du T2 2026',
  'aiworkspace.demo.quarterly.introText': 'Voici un tableau de ventes ordinaire du T2 2026 : chiffre d’affaires, coût, objectif et chiffre d’affaires du trimestre précédent par région et par produit. Vous pouvez modifier les chiffres directement en mode Source de données, ou décrire en une phrase l’analyse souhaitée dans le vœu sur le canevas, puis appuyer trois fois sur son bouton : Analyser, Écrire la macro, Exécuter la macro. Chaque étape écrit son résultat dès qu’elle se termine ; si l’une ne vous convient pas, revenez à l’onglet précédent et relancez-la, ou annulez-la. La flèche bleue en pointillés montre ce que le vœu lit, les flèches orange ce qu’il a produit. Quand les données changent, exécutez de nouveau la macro.',
