  'aiworkspace.demo.film.script.scenes': 'Séquences',
  'aiworkspace.demo.film.script.scene1': '1. Toit-terrasse · nuit · pluie : Che reçoit une commande urgente ; Xiaoman annonce « Destination : tour Cloudtop ». (Che, Xiaoman)',
  'aiworkspace.demo.film.script.scene2': '2. Rue néon · nuit : les deux se frayent un chemin dans un marché nocturne bondé, en esquivant les drones de patrouille. (Che, Xiaoman)',
  'aiworkspace.demo.film.script.scene3': '3. Restaurant de nouilles de Zhou · nuit : Zhou tend un bol de nouilles chaud et révèle le secret du colis. (Che, Zhou)',
