  'aiworkspace.demo.film.howtoName': 'Comment utiliser ce canevas',
  'aiworkspace.demo.film.howto.title': 'Flux de travail d’un court métrage IA : fiches des personnages → visuels des personnages → storyboard → montage final',
  'aiworkspace.demo.film.howto.text': 'Un flux de génération de gauche à droite dans lequel chaque nœud est un objet ordinaire du canevas : à gauche, le scénario, la table des personnages et le style, que vous pouvez modifier directement ; chaque étape est un vœu, et sur chaque carte vous appuyez tour à tour sur Analyser, Écrire la macro et Exécuter la macro — chaque étape écrit son résultat dès qu’elle se termine. Ce que produit une étape est l’entrée de la suivante : exécutez donc les étapes de gauche à droite ; les flèches bleues en pointillés partent de ce qu’un vœu lit, les flèches orange vont vers ce qu’il a produit. Si vous modifiez la table des personnages ou le scénario, les résultats en aval sont marqués comme périmés ; relancez-les l’un après l’autre. Les images et la vidéo sont générées par les modèles d’IA de la Zone.',
  'aiworkspace.demo.film.surface': 'Flux de travail du court métrage',
  'aiworkspace.demo.film.wish1.title': 'Vœu ① : générer les fiches des personnages',
  'aiworkspace.demo.film.wish1.prompt': 'À partir de la table « {{characters}} » et de « {{style}} », génère pour chaque personnage une fiche en format portrait, accompagnée d’une courte note de présentation. Conserve la couleur principale et les accessoires de chaque personnage pour que le storyboard puisse s’y référer ensuite.',
  'aiworkspace.demo.film.wish1.output': 'Fiches des personnages',
  'aiworkspace.demo.film.wish2.title': 'Vœu ② : générer le storyboard',
  'aiworkspace.demo.film.wish2.prompt': 'À partir des séquences de « {{script}} », avec « {{sheets}} » et « {{style}} », génère un storyboard : un plan par séquence ; produis un découpage technique (n° de plan, séquence, valeur de plan, personnages, action, durée) et une image pour chaque plan.',
  'aiworkspace.demo.film.wish2.output': 'Storyboard',
  'aiworkspace.demo.film.wish3.title': 'Vœu ③ : générer l’aperçu du montage final',
  'aiworkspace.demo.film.wish3.prompt': 'À partir de « {{storyboard}} », génère une vidéo d’aperçu du montage final : un seul clip continu d’environ 8 secondes (16:9) qui suit les plans dans l’ordre du découpage, avec l’image du premier plan comme image de référence ; rédige aussi une note indiquant le nombre de plans et la durée totale du découpage.',
